create function pg_temp.assert_port(ok boolean)returns void language plpgsql as $$begin if ok is not true then raise exception 'portability_assertion';end if;end$$;
create function pg_temp.deny_port(q text,c text)returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=c then return;end if;raise;end;raise exception 'portability_expected_denial';end$$;
create temporary table saved_port(op text,i jsonb,r jsonb);grant all on saved_port to authenticated;
