select set_config('request.jwt.claim.sub','a8100000-0000-4000-8000-000000000001',true);
do $$declare w uuid:='b8100000-0000-4000-8000-000000000001';o jsonb;donor jsonb;cust jsonb;con jsonb;s jsonb;l jsonb;n jsonb;p jsonb;i jsonb;r jsonb;begin
